// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime1, uint256 warpTime2, bool isEvenBlock) public {
        // Ensure timestamps are strictly increasing and warpTime2 > warpTime1
        warpTime1 = bound(warpTime1, 1, 1000000);
        warpTime2 = bound(warpTime2, warpTime1 + 1, 1000001);

        // Set block number to a value where block.number % 15 != 0 (the buggy condition triggers transfer)
        // We want to test when the buggy contract would transfer (block.number % 15 != 0)
        // The reference contract does NOT transfer when block.number % 15 != 0
        vm.assume(block.number % 15 != 0);

        // First call: send 10 ether with a valid timestamp
        vm.warp(warpTime1);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        uint256 balanceAfterFirst = address(c).balance;

        // Second call: send 10 ether again with a later timestamp
        vm.warp(warpTime2);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        assertTrue(success2);

        uint256 balanceAfterSecond = address(c).balance;

        // The reference contract should have increased balance by 10 ether (it does not transfer when block.number % 15 != 0)
        // The buggy contract would have transferred all balance on second call, making balance potentially zero or less
        // General rule: balance should have increased by at least 10 ether (no net decrease)
        assertTrue(balanceAfterSecond >= balanceAfterFirst + 10 ether - 1);
    }
}

